private String[] appendValue(String[] values, final String value) {
    if (value == null) {
        return values;
    }
    String[] newValues = new String[values.length + 1];
    System.arraycopy(values, 0, newValues, 0, values.length);
    newValues[newValues.length - 1] = value;
    return newValues;
}
